import type { Column, Typed } from '../Column'

type GuidColumnType<Type extends string = string, Default extends Type = Type> = Column<Type, Default>

/**
 * A Column for a GUID (Globally Unique Identifier) type field.
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @param config - an object that can include all base `Column` properties
 *   * **maxLength**? - maximum number of characters allowed in this field (typically 32 or 36 for GUIDs)
 */
export function GuidColumn<
    const Type extends string,
    const Default extends Type,
    const C extends GuidColumnType<Type, Default>,
>(config: C & GuidColumnType<Type, Default>) {
    return config as Typed<Type, C>
}
